function renderDetail(id){
  const s = sports.find(x=>x.id===id);
  const hasPartialTools = s.id==='nba' || s.id==='wnba' || s.id==='nfl' || s.id==='cfb';
  const hasMLBTools = s.id==='mlb';
  detailPanel.innerHTML = `
    <div class="detail-top">
      <h3 class="detail-title">${s.title}</h3>
      <span class="detail-badge ${s.badge}">${s.badge==='full'?'Confirmed wording':'Analogy / pending'}</span>
      ${s.rawText ? `<button class="copy-btn" id="copyBtn">Copy rule text</button>` : ''}
    </div>
    ${s.image ? `<img class="source-shot" src="${s.image}" alt="${s.name} Reboot policy screenshot">
                 <div class="source-caption">Source screenshot — ${s.name} Reboot policy</div>` : ''}
    <div class="detail-body">${s.body}</div>
    ${hasPartialTools ? partialToolsBlock(s.id) : ''}
    ${hasMLBTools ? mlbToolsBlock() : ''}
    ${s.note ? `<div class="note">${s.note}</div>` : `<div class="note info">This rule reflects the exact policy text provided.</div>`}
  `;
  if (hasMLBTools){
    initMLBTools();
  }
  if (hasPartialTools){
    const squares = s.id === 'nba' ? partialSquares : (s.id === 'wnba' ? partialSquaresWNBA : (s.id === 'cfb' ? partialSquaresCFB : partialSquaresNFL));
    renderPartialGrid('partialGrid', squares, { images: true });
    initSpielGenerator(s.id);
    initPartialSpielGenerator(`${s.id}1h`);

    const showBtn = document.getElementById('showPartialSpielBtn');
    const spielSection = document.getElementById('partialSpielSection');
    showBtn.addEventListener('click', ()=>{
      const isHidden = spielSection.style.display === 'none';
      spielSection.style.display = isHidden ? 'block' : 'none';
      showBtn.textContent = isHidden ? 'Hide response generator' : 'Generate a response for a partial-period question';
      if (isHidden) spielSection.scrollIntoView({ behavior:'smooth', block:'nearest' });
    });

    if (s.id === 'nfl'){
      initDefensiveSpielGenerator();
      const showDefBtn = document.getElementById('showDefensiveSpielBtn');
      const defSection = document.getElementById('defensiveSpielSection');
      showDefBtn.addEventListener('click', ()=>{
        const isHidden = defSection.style.display === 'none';
        defSection.style.display = isHidden ? 'block' : 'none';
        showDefBtn.textContent = isHidden ? 'Hide response generator' : 'Generate a response for a defensive-player question';
        if (isHidden) defSection.scrollIntoView({ behavior:'smooth', block:'nearest' });
      });
    }

    if (s.id === 'cfb'){
      initCFBNotListedSpielGenerator();
      const showListBtn = document.getElementById('showCFBNotListedSpielBtn');
      const listSection = document.getElementById('cfbNotListedSpielSection');
      showListBtn.addEventListener('click', ()=>{
        const isHidden = listSection.style.display === 'none';
        listSection.style.display = isHidden ? 'block' : 'none';
        showListBtn.textContent = isHidden ? 'Hide response generator' : "Generate a response for a player not on the Reboots list";
        if (isHidden) listSection.scrollIntoView({ behavior:'smooth', block:'nearest' });
      });
    }
  }
  if (s.rawText){
    const btn = document.getElementById('copyBtn');
    btn.addEventListener('click', ()=>{
      navigator.clipboard.writeText(s.rawText).then(()=>{
        btn.textContent = 'Copied ✓';
        btn.classList.add('copied');
        setTimeout(()=>{ btn.textContent='Copy rule text'; btn.classList.remove('copied'); }, 1800);
      });
    });
  }
}

function selectSport(id){
  renderRack(id);
  renderDetail(id);
  const simSection = document.getElementById('simulator');
  if (simSection) simSection.style.display = id === 'mlb' ? 'none' : '';
}

// ---------------- Simulator ----------------
const state = { pick:'more', hit:'no', ret:'no', stat:'fullgame', exit:35 };

document.querySelectorAll('.toggle-btn').forEach(btn=>{
  btn.addEventListener('click', ()=>{
    const group = btn.dataset.group;
    document.querySelectorAll(`.toggle-btn[data-group="${group}"]`).forEach(b=>b.classList.remove('on'));
    btn.classList.add('on');
    state[group === 'return' ? 'ret' : group] = btn.dataset.val;
    updateVerdict();
  });
});

const exitSlider = document.getElementById('exitSlider');
const exitMarker = document.getElementById('exitMarker');
exitSlider.addEventListener('input', ()=>{
  state.exit = +exitSlider.value;
  exitMarker.style.left = state.exit + '%';
  updateVerdict();
});

const verdictCard = document.getElementById('verdictCard');
const verdictStatus = document.getElementById('verdictStatus');
const verdictDetail = document.getElementById('verdictDetail');

function updateVerdict(){
  const { pick, hit, ret, stat, exit } = state;
  const exitedFirstHalf = exit < 50;
  let status, cls, detail;

  if (hit === 'yes'){
    // hit projection before leaving -> normal grading
    if (pick === 'more'){ status='WON'; cls='win'; detail='The athlete cleared the projection before exiting, so this More pick grades normally — a win, reboot or not.'; }
    else { status='LOST'; cls='lose'; detail='The athlete cleared the projection before exiting, so this Less pick grades normally — a loss.'; }
  } else if (pick === 'less'){
    // rule: Less always wins on a reboot-eligible or reboot-triggered projection
    status='WON'; cls='win'; detail='Less picks win on a rebooted projection, regardless of when or how the athlete exits.';
  } else if (stat === 'partial'){
    // partial-period combo stat -> never reboot-eligible, graded on final box score as normal
    status='LOST'; cls='lose'; detail='This is a partial-period combo stat (e.g. Quarter/Half + achievement) — those are never Reboot-eligible, so it grades on the final box score as normal.';
  } else if (exitedFirstHalf && ret === 'no'){
    status='REBOOT'; cls='reboot'; detail='Entered the first half, exited, and never returned in the second half — this More pick is protected by the Reboot policy.';
  } else if (!exitedFirstHalf){
    status='LOST'; cls='lose'; detail='The exit happened in the second half (or the player never left in the first half), so the Reboot condition is not met — graded as normal.';
  } else {
    status='LOST'; cls='lose'; detail='The athlete returned to play in the second half, so the Reboot condition is not met — graded as normal.';
  }

  verdictStatus.textContent = status;
  verdictCard.className = 'verdict-card ' + cls;
  verdictDetail.textContent = detail;
}
updateVerdict();

// ---------------- Spiel generator (NBA panel only) ----------------
function lastName(fullName){
  const parts = fullName.trim().split(/\s+/).filter(Boolean);
  return parts.length ? parts[parts.length - 1] : '';
}

function initSpielGenerator(sportId='nba'){
  const spielPlayer = document.getElementById('spielPlayer');
  const spielMinutes = document.getElementById('spielMinutes');
  const spielQuarter = document.getElementById('spielQuarter');
  const spielText = document.getElementById('spielText');
  const spielCopyBtn = document.getElementById('spielCopyBtn');
  if (!spielPlayer) return;

  const isNFL = sportId === 'nfl';

  function buildSpiel(){
    const name = spielPlayer.value.trim() || "[Player's Name]";
    const last = spielPlayer.value.trim() ? lastName(spielPlayer.value) : "[Player's Last Name]";
    const mins = spielMinutes.value.trim() || (isNFL ? '[Timestamp]' : '[minutes played]');
    const qtr = spielQuarter.value;

    let plain;
    if (isNFL){
      plain =
`Thank you so much for reaching out.

I truly understand your concern regarding ${name}, and I appreciate you taking the time to inquire.

After a thorough review with our scoring team, we've confirmed that ${name} is not eligible for a reboot. He did participate in the second half of the game—specifically appearing on a snap at the ${mins} in the ${qtr}—which finalizes the score and unfortunately makes it unable to be adjusted.

I know this might not be the outcome you were hoping for, and I genuinely appreciate your understanding. If you have any other questions or need further clarification, please don't hesitate to reach out. We're always here to help.`;
    } else {
      plain =
`Thank you so much for reaching out. I truly understand your concern regarding ${name}, and I appreciate you taking the time to inquire.

After a thorough review with our scoring team, we've confirmed that ${name} is not eligible for a Reboot. He played ${mins} in the ${qtr}, which confirms his appearance in the second half.

As a reminder, Reboots can only be applied to players who played in the first half but did not return or appear in the second half. Since ${last} appeared in the second half, his projection is finalized and cannot be adjusted under current PrizePicks policy.

I know this might not be the outcome you were hoping for, and I genuinely appreciate your understanding. If you have any other questions or need further clarification, please don't hesitate to reach out. We're always here to help.`;
    }

    let highlighted = plain
      .replaceAll(name, `<span class="fill">${name}</span>`)
      .replaceAll(mins, `<span class="fill">${mins}</span>`)
      .replaceAll(qtr, `<span class="fill">${qtr}</span>`);
    if (!isNFL) highlighted = highlighted.replaceAll(last, `<span class="fill">${last}</span>`);

    spielText.innerHTML = highlighted;
    spielText.dataset.plain = plain;
  }

  [spielPlayer, spielMinutes, spielQuarter].forEach(el=>{
    el.addEventListener('input', buildSpiel);
    el.addEventListener('change', buildSpiel);
  });
  buildSpiel();

  spielCopyBtn.addEventListener('click', ()=>{
    navigator.clipboard.writeText(spielText.dataset.plain || '').then(()=>{
      spielCopyBtn.textContent = 'Copied ✓';
      spielCopyBtn.classList.add('copied');
      setTimeout(()=>{ spielCopyBtn.textContent='Copy response'; spielCopyBtn.classList.remove('copied'); }, 1800);
    });
  });
}

