function buildPartialSpiel(key){
  const c = partialSpielCopy[key];
  if (!c) return `Thank you for reaching out!\uD83D\uDC99\n\nThat square isn't eligible for a Reboot under current PrizePicks policy.\n\nI know this might not be the outcome you were hoping for, and I genuinely appreciate your understanding. If you have any other questions or need further clarification, please don't hesitate to reach out. We're always here to help.`;

  if (c.official){
    return `Thank you for reaching out!\uD83D\uDC99

Reboot: ${c.official}

I know this might not be the outcome you were hoping for, and I genuinely appreciate your understanding. If you have any other questions or need further clarification, please don't hesitate to reach out. We're always here to help.`;
  }

  return `Thank you for reaching out!\uD83D\uDC99

The reason an ${c.label} square isn't eligible for a Reboot is because the square only covers the athlete's performance during ${c.period}.

Our Reboot policy is specifically designed for full-game ${c.sport} squares and requires an athlete to enter in the first half, leave the game, and not return at any point in the second half. ${c.detail}

For this reason, ${c.label} squares are not eligible for Reboots under the current policy.

I know this might not be the outcome you were hoping for, and I genuinely appreciate your understanding. If you have any other questions or need further clarification, please don't hesitate to reach out. We're always here to help.`;
}

function initPartialSpielGenerator(defaultKey='nba1h'){
  const toggleWrap = document.getElementById('partialSpielToggle');
  const outputEl = document.getElementById('partialSpielText');
  const copyBtn = document.getElementById('partialSpielCopyBtn');
  if (!toggleWrap) return;

  function render(key){
    const plain = buildPartialSpiel(key);
    outputEl.textContent = plain;
    outputEl.dataset.plain = plain;
  }

  toggleWrap.querySelectorAll('.toggle-btn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      toggleWrap.querySelectorAll('.toggle-btn').forEach(b=>b.classList.remove('on'));
      btn.classList.add('on');
      render(btn.dataset.partial);
    });
  });

  copyBtn.addEventListener('click', ()=>{
    navigator.clipboard.writeText(outputEl.dataset.plain || '').then(()=>{
      copyBtn.textContent = 'Copied ✓';
      copyBtn.classList.add('copied');
      setTimeout(()=>{ copyBtn.textContent='Copy response'; copyBtn.classList.remove('copied'); }, 1800);
    });
  });

  render(defaultKey);
}

// ---------------- General-rules spiel buttons (static section, not per-sport) ----------------
function initGeneralRuleSpiels(){
  const lessWinCopy =
`Thanks for reaching out! When a player exits the game early and the square becomes Reboot-eligible, any square with LESS selected on that projection automatically wins — that's just how the projection resolved, no additional review needed.

Reboots exist to protect MORE selections from being unfairly graded as a loss when a player leaves early. Since a LESS pick already benefits from the player not finishing the game, there's nothing for a Reboot to fix — the win stands under our standard grading rules.

You can find the full policy on our official Reboots page: https://www.prizepicks.com/reboots

I know this might not be the outcome you were hoping for, and I genuinely appreciate your understanding. If you have any other questions or need further clarification, please don't hesitate to reach out. We're always here to help.`;

  const gradedNormallyCopy =
`Thanks for reaching out! If a player already reached or exceeded their projection before leaving the game, the pick is graded normally — MORE wins, LESS loses — exactly as it would if the player had stayed in for the full game.

The Reboot policy is designed to protect picks that are still undecided when a player exits early. Since the outcome here was already determined before that player left the game, there's no unresolved grading for a Reboot to apply to.

You can find the full policy on our official Reboots page: https://www.prizepicks.com/reboots

I know this might not be the outcome you were hoping for, and I genuinely appreciate your understanding. If you have any other questions or need further clarification, please don't hesitate to reach out. We're always here to help.`;

  const wireCopyBtn = (id, text) => {
    const btn = document.getElementById(id);
    if (!btn) return;
    btn.addEventListener('click', ()=>{
      navigator.clipboard.writeText(text).then(()=>{
        const original = btn.textContent;
        btn.textContent = 'Copied ✓';
        btn.classList.add('copied');
        setTimeout(()=>{ btn.textContent = original; btn.classList.remove('copied'); }, 1800);
      });
    });
  };

  wireCopyBtn('lessWinSpielBtn', lessWinCopy);
  wireCopyBtn('gradedNormallySpielBtn', gradedNormallyCopy);
}

