// ---------------- Other (non-Reboot-eligible) grid ----------------
const otherGrid = document.getElementById('otherGrid');
const otherEmpty = document.getElementById('otherEmpty');
const otherCount = document.getElementById('otherCount');
const otherSearchInput = document.getElementById('otherSearch');
let selectedOtherCode = null;

function renderOtherGrid(filter=''){
  const q = filter.trim().toLowerCase();

  if (!q){
    otherGrid.innerHTML = '';
    otherGrid.style.display = 'none';
    otherEmpty.style.display = 'none';
    otherCount.textContent = `Start typing to search ${otherSquares.length} projection types`;
    return;
  }

  const matches = otherSquares.filter(o => o.code.toLowerCase().includes(q) || o.label.toLowerCase().includes(q));

  otherCount.textContent = `${matches.length} of ${otherSquares.length} projection types`;
  otherEmpty.style.display = matches.length === 0 ? 'block' : 'none';
  otherGrid.style.display = matches.length === 0 ? 'none' : 'grid';

  otherGrid.innerHTML = matches.map((o) => {
    const idx = otherSquares.indexOf(o);
    return `
    <div class="other-card${o.code === selectedOtherCode ? ' selected' : ''}" data-idx="${idx}">
      ${o.image
        ? `<img src="${o.image}" alt="${o.code} not eligible for Reboot screenshot">`
        : `<div class="other-card-thumb"><span>${o.code}</span></div>`}
      <div class="other-card-body">
        <div class="other-card-code">${o.code}</div>
        <div class="other-card-foot">
          <span class="status-pill">Not eligible</span>
          <button class="mini-copy" data-idx="${idx}">Copy</button>
        </div>
      </div>
    </div>
  `;
  }).join('');

  otherGrid.querySelectorAll('.other-card').forEach(card=>{
    card.addEventListener('click', (e)=>{
      if (e.target.closest('.mini-copy')) return;
      const o = otherSquares[+card.dataset.idx];
      selectOtherSpiel(o.code);
    });
  });

  otherGrid.querySelectorAll('.mini-copy').forEach(btn=>{
    btn.addEventListener('click', (e)=>{
      e.stopPropagation();
      const o = otherSquares[+btn.dataset.idx];
      navigator.clipboard.writeText(o.rawText).then(()=>{
        btn.textContent = 'Copied ✓';
        btn.classList.add('copied');
        setTimeout(()=>{ btn.textContent='Copy'; btn.classList.remove('copied'); }, 1600);
      });
    });
  });
}

if (otherSearchInput){
  otherSearchInput.addEventListener('input', ()=> renderOtherGrid(otherSearchInput.value));
}

// ---------------- Other (non-Reboot-eligible) spiel generator ----------------
function buildOtherSpiel(code){
  const o = otherSquares.find(x => x.code === code);
  if (!o) return `Thank you for reaching out!\uD83D\uDC99\n\nThat square isn't eligible for a Reboot under current PrizePicks policy.\n\nI know this might not be the outcome you were hoping for, and I genuinely appreciate your understanding. If you have any other questions or need further clarification, please don't hesitate to reach out. We're always here to help.`;

  return `Thank you for reaching out!\uD83D\uDC99

I completely understand wanting a Reboot here, but ${o.code} squares aren't eligible for a Reboot under our current PrizePicks policy. This holds no matter how the game or event plays out — Reboots are currently limited to specific full-game squares on select sports, and this square falls outside of that list.

You can find the full policy on our official Reboots page: https://www.prizepicks.com/reboots

I know this might not be the outcome you were hoping for, and I genuinely appreciate your understanding. If you have any other questions or need further clarification, please don't hesitate to reach out. We're always here to help.`;
}

function selectOtherSpiel(code){
  selectedOtherCode = code;
  const o = otherSquares.find(x => x.code === code);
  const selectedEl = document.getElementById('otherSpielSelected');
  const outputEl = document.getElementById('otherSpielText');
  const copyBtn = document.getElementById('otherSpielCopyBtn');
  if (!o || !selectedEl || !outputEl || !copyBtn) return;

  selectedEl.innerHTML = `<span class="other-spiel-selected-code">${o.code}</span>`;

  const plain = buildOtherSpiel(code);
  outputEl.textContent = plain;
  outputEl.dataset.plain = plain;
  outputEl.style.color = '';
  copyBtn.disabled = false;

  // Keep the grid's highlighted card in sync if it's currently visible
  if (otherSearchInput && otherSearchInput.value.trim()) renderOtherGrid(otherSearchInput.value);
}

function initOtherSpielGenerator(){
  const copyBtn = document.getElementById('otherSpielCopyBtn');
  if (!copyBtn) return;

  copyBtn.addEventListener('click', ()=>{
    const outputEl = document.getElementById('otherSpielText');
    navigator.clipboard.writeText(outputEl.dataset.plain || '').then(()=>{
      copyBtn.textContent = 'Copied ✓';
      copyBtn.classList.add('copied');
      setTimeout(()=>{ copyBtn.textContent='Copy response'; copyBtn.classList.remove('copied'); }, 1800);
    });
  });
}

